import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    words = []
    for _ in range(n):
        words.append(next(iterator))

    MOD = 998244353

    max_len = 5
    alphabet_size = 26

    if m == 0:
        print(0)
        return

    word_map = {}
    for w in words:
        word_map[w] = True

    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(1, m + 1):
        total = 0
        for w in words:
            L = len(w)
            if i >= L:
                prev_idx = i - L
                if dp[prev_idx] > 0:
                    total = (total + dp[prev_idx]) % MOD
        dp[i] = total

    if dp[m] == 0:
        print(0)
        return

    transitions = []
    for w in words:
        L = len(w)
        transitions.append(L)

    if m < min(transitions):
        print(0)
        return

    if m <= 100000:
        print(dp[m] % MOD)
        return

    mat_size = max(transitions)
    if mat_size == 0:
        print(0)
        return

    base_mat = [[0] * mat_size for _ in range(mat_size)]
    for i in range(mat_size):
        if i + 1 < mat_size:
            base_mat[i][i+1] = 1

    for L in transitions:
        if L <= mat_size:
            base_mat[L-1][0] = (base_mat[L-1][0] + 1) % MOD

    def mat_mul(A, B):
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k] == 0:
                    continue
                for j in range(size):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        size = len(A)
        res = [[0] * size for _ in range(size)]
        for k in range(size):
            res[k][k] = 1
        while p > 0:
            if p & 1:
                res = mat_mul(res, A)
            A = mat_mul(A, A)
            p >>= 1
        return res

    if m <= mat_size:
        print(dp[m] % MOD)
        return

    init_vec = [dp[i] for i in range(mat_size)]

    power = m - mat_size
    T = mat_pow(base_mat, power)

    final_val = 0
    for j in range(mat_size):
        term = 0
        for k in range(mat_size):
            term = (term + init_vec[k] * T[k][j]) % MOD
        final_val = (final_val + term) % MOD

    print(final_val)

solve()
